const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");

// Icons
const { FaEthereum, FaFire, FaGasPump, FaChartPie, FaLock, FaChartLine, FaGlobeAmericas, FaBullseye } = require("react-icons/fa");

function renderIconSvg(IconComponent, color, size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// Color palette - Ethereum-inspired dark theme
const C = {
  bg_dark: "0B1120",      // deep navy/black
  bg_card: "141E33",      // card background
  bg_mid: "1A2540",       // mid-tone panel
  accent: "627EEA",       // ETH purple-blue
  accent2: "8B5CF6",      // vivid purple
  green: "10B981",        // mint green for positive
  red: "EF4444",          // red for burn/negative
  orange: "F59E0B",       // amber accent
  white: "FFFFFF",
  light: "E2E8F0",        // light gray text
  muted: "94A3B8",        // muted text
  dim: "64748B",          // dim text
  card_border: "1E3A5F",
};

const FONT_HEAD = "Trebuchet MS";
const FONT_BODY = "Calibri";

const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.3 });
const makeCardShadow = () => ({ type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.2 });

function addSlideNumber(slide, num) {
  slide.addText(`${num} / 8`, {
    x: 8.8, y: 5.2, w: 1, h: 0.3,
    fontSize: 9, fontFace: FONT_BODY, color: C.dim, align: "right"
  });
}

function addTopBar(slide) {
  slide.addShape("rectangle", {
    x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent }
  });
}

async function buildDeck() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Ultra Sound Money Analytics";
  pres.title = "Ultra Sound Money: Ethereum's Post-Merge Supply Dynamics and Monetary Premium";

  // Pre-render icons
  const iconEth = await iconToBase64Png(FaEthereum, "#627EEA", 256);
  const iconFire = await iconToBase64Png(FaFire, "#EF4444", 256);
  const iconGas = await iconToBase64Png(FaGasPump, "#F59E0B", 256);
  const iconPie = await iconToBase64Png(FaChartPie, "#627EEA", 256);
  const iconLock = await iconToBase64Png(FaLock, "#10B981", 256);
  const iconLine = await iconToBase64Png(FaChartLine, "#8B5CF6", 256);
  const iconGlobe = await iconToBase64Png(FaGlobeAmericas, "#627EEA", 256);
  const iconTarget = await iconToBase64Png(FaBullseye, "#F59E0B", 256);

  // ============================================================
  // SLIDE 1: Title Slide
  // ============================================================
  {
    const slide = pres.addSlide();
    slide.background = { color: C.bg_dark };

    // Decorative accent bar at top
    slide.addShape("rectangle", {
      x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.accent }
    });

    // ETH icon
    slide.addImage({ data: iconEth, x: 0.7, y: 0.6, w: 0.7, h: 0.7 });

    // Title
    slide.addText("Ultra Sound Money", {
      x: 0.7, y: 1.4, w: 8.6, h: 1.0,
      fontSize: 44, fontFace: FONT_HEAD, color: C.white, bold: true, margin: 0
    });

    // Subtitle
    slide.addText("Ethereum's Supply Dynamics & Monetary Thesis", {
      x: 0.7, y: 2.3, w: 8.6, h: 0.5,
      fontSize: 22, fontFace: FONT_HEAD, color: C.accent, margin: 0
    });

    // Thin separator line
    slide.addShape("rectangle", {
      x: 0.7, y: 3.0, w: 3.0, h: 0.03, fill: { color: C.accent2 }
    });

    // Key context stats row
    const statY = 3.4;
    const stats = [
      { label: "CURRENT SUPPLY", value: "121,603,980 ETH" },
      { label: "BASE GAS", value: "0.1 Gwei" },
      { label: "ETH PRICE", value: "$2,243" },
    ];
    stats.forEach((s, i) => {
      const sx = 0.7 + i * 3.0;
      slide.addText(s.label, {
        x: sx, y: statY, w: 2.8, h: 0.3,
        fontSize: 10, fontFace: FONT_BODY, color: C.muted, charSpacing: 2, margin: 0
      });
      slide.addText(s.value, {
        x: sx, y: statY + 0.3, w: 2.8, h: 0.45,
        fontSize: 20, fontFace: FONT_HEAD, color: C.white, bold: true, margin: 0
      });
    });

    // Data source
    slide.addText("Data: ultrasound.money", {
      x: 0.7, y: 4.9, w: 4, h: 0.3,
      fontSize: 10, fontFace: FONT_BODY, color: C.dim, italic: true, margin: 0
    });

    // Decorative shape - right side abstract
    slide.addShape("rectangle", {
      x: 9.2, y: 0.08, w: 0.8, h: 5.545,
      fill: { color: C.accent, transparency: 8 }
    });
  }

  // ============================================================
  // SLIDE 2: Supply Change Snapshot (waterfall chart)
  // ============================================================
  {
    const slide = pres.addSlide();
    slide.background = { color: C.bg_dark };
    addTopBar(slide);
    addSlideNumber(slide, 2);

    // Title
    slide.addText("ETH Supply Growing at +0.83%/Year", {
      x: 0.7, y: 0.3, w: 8.6, h: 0.55,
      fontSize: 28, fontFace: FONT_HEAD, color: C.white, bold: true, margin: 0
    });
    slide.addText("Only 192 ETH Burned in 7 Days — 0.01x Offset Ratio", {
      x: 0.7, y: 0.85, w: 8.6, h: 0.35,
      fontSize: 14, fontFace: FONT_BODY, color: C.muted, margin: 0
    });

    // Left side: Waterfall-style bar chart using shapes
    // Issuance bar (tall, green)
    const barBaseY = 4.2;
    const barMaxH = 2.6;
    const issBarH = barMaxH;
    const burnBarH = barMaxH * (192.39 / 19638.29); // proportional

    // Issuance bar
    slide.addShape("rectangle", {
      x: 1.5, y: barBaseY - issBarH, w: 1.8, h: issBarH,
      fill: { color: C.green }, shadow: makeCardShadow()
    });
    slide.addText("+19,638 ETH", {
      x: 1.5, y: barBaseY - issBarH - 0.35, w: 1.8, h: 0.3,
      fontSize: 14, fontFace: FONT_HEAD, color: C.green, bold: true, align: "center", margin: 0
    });
    slide.addText("Issuance", {
      x: 1.5, y: barBaseY + 0.05, w: 1.8, h: 0.3,
      fontSize: 12, fontFace: FONT_BODY, color: C.muted, align: "center", margin: 0
    });

    // Burn bar (tiny, red)
    const burnVisH = Math.max(burnBarH, 0.04);
    slide.addShape("rectangle", {
      x: 4.0, y: barBaseY - burnVisH, w: 1.8, h: burnVisH,
      fill: { color: C.red }, shadow: makeCardShadow()
    });
    slide.addText("-192 ETH", {
      x: 4.0, y: barBaseY - 0.4, w: 1.8, h: 0.3,
      fontSize: 14, fontFace: FONT_HEAD, color: C.red, bold: true, align: "center", margin: 0
    });
    slide.addText("Burn", {
      x: 4.0, y: barBaseY + 0.05, w: 1.8, h: 0.3,
      fontSize: 12, fontFace: FONT_BODY, color: C.muted, align: "center", margin: 0
    });

    // Net bar
    const netBarH = barMaxH * (19445.89 / 19638.29);
    slide.addShape("rectangle", {
      x: 6.5, y: barBaseY - netBarH, w: 1.8, h: netBarH,
      fill: { color: C.orange }, shadow: makeCardShadow()
    });
    slide.addText("+19,446 ETH", {
      x: 6.5, y: barBaseY - netBarH - 0.35, w: 1.8, h: 0.3,
      fontSize: 14, fontFace: FONT_HEAD, color: C.orange, bold: true, align: "center", margin: 0
    });
    slide.addText("Net (7d)", {
      x: 6.5, y: barBaseY + 0.05, w: 1.8, h: 0.3,
      fontSize: 12, fontFace: FONT_BODY, color: C.muted, align: "center", margin: 0
    });

    // Baseline
