    });

    // Native bar chart for issuance vs burn vs net
    slide.addChart(pres.charts.BAR, [
      {
        name: "Issuance",
        labels: ["Issuance", "Burn", "Net (7d)"],
        values: [19638, 0, 0]
      },
      {
        name: "Burn",
        labels: ["Issuance", "Burn", "Net (7d)"],
        values: [0, 192, 0]
      },
      {
        name: "Net",
        labels: ["Issuance", "Burn", "Net (7d)"],
        values: [0, 0, 19446]
      }
    ], {
      x: 0.3, y: 1.2, w: 6.5, h: 3.8,
      barDir: "col",
      barGrouping: "stacked",
      chartColors: [C.green, C.red, C.orange],
      chartArea: { fill: { color: C.bg_dark } },
