      catAxisLabelColor: C.light,
      catAxisLabelFontSize: 11,
      catAxisLabelFontFace: FONT_BODY,
      valAxisLabelColor: C.muted,
      valAxisLabelFontSize: 9,
      valGridLine: { color: C.bg_card, size: 0.5 },
      catGridLine: { style: "none" },
      showValue: true,
      dataLabelPosition: "outEnd",
      dataLabelColor: C.light,
      dataLabelFontSize: 11,
      dataLabelFontFace: FONT_HEAD,
      showLegend: true,
      legendPos: "b",
      legendColor: C.muted,
      legendFontSize: 9,
    });

    // Stat cards on right
    card(slide, pres, 7.2, 1.4, 2.5, 1.3);
    slide.addText("TOTAL SUPPLY", {
      x: 7.2, y: 1.5, w: 2.5, h: 0.25,
      fontSize: 9, fontFace: FONT_BODY, color: C.muted, align: "center", charSpacing: 2, margin: 0
    });
    slide.addText("121.6M", {
      x: 7.2, y: 1.8, w: 2.5, h: 0.5,
      fontSize: 28, fontFace: FONT_HEAD, color: C.white, bold: true, align: "center", margin: 0
    });
    slide.addText("ETH", {
      x: 7.2, y: 2.3, w: 2.5, h: 0.25,
      fontSize: 12, fontFace: FONT_BODY, color: C.accent, align: "center", margin: 0
    });

    card(slide, pres, 7.2, 2.9, 2.5, 1.3);
    slide.addText("OFFSET RATIO", {
      x: 7.2, y: 3.0, w: 2.5, h: 0.25,
      fontSize: 9, fontFace: FONT_BODY, color: C.muted, align: "center", charSpacing: 2, margin: 0
    });
    slide.addText("0.01x", {
      x: 7.2, y: 3.3, w: 2.5, h: 0.5,
      fontSize: 28, fontFace: FONT_HEAD, color: C.red, bold: true, align: "center", margin: 0
    });
    slide.addText("~1% of issuance", {
      x: 7.2, y: 3.8, w: 2.5, h: 0.25,
      fontSize: 11, fontFace: FONT_BODY, color: C.muted, align: "center", margin: 0
    });
  }

  // ============================================================
  // SLIDE 3: Gas & Burn Mechanics (fixed title, layout)
  // ============================================================
  {
    const slide = pres.addSlide();
    slide.background = { color: C.bg_dark };
    addTopBar(slide, pres);
    addSlideNumber(slide, pres, 3);

    slide.addText("Gas at Historic Lows — Burn Suppressed", {
      x: 0.7, y: 0.3, w: 8.6, h: 0.5,
