      titleColor: C.light, titleFontFace: FONT_BODY, titleFontSize: 12,
      chartColors: [C.accent, C.orange, C.accent2],
      showPercent: true,
      dataLabelColor: C.light,
      dataLabelFontSize: 10,
      showLegend: true, legendPos: "b", legendColor: C.muted, legendFontSize: 9,
    });

    // Daily economics panel
    card(slide, pres, 5.3, 3.2, 4.4, 2.1);
    slide.addText("DAILY ECONOMICS", {
      x: 5.5, y: 3.3, w: 4.0, h: 0.3,
      fontSize: 10, fontFace: FONT_BODY, color: C.accent, bold: true, charSpacing: 2, margin: 0
    });
    slide.addText([
      { text: "PoS Issuance: ", options: { color: C.muted, fontSize: 13, fontFace: FONT_BODY } },
      { text: "~2,800 ETH/day", options: { color: C.green, fontSize: 13, fontFace: FONT_BODY, bold: true, breakLine: true } },
      { text: "Fee Burn (normalized): ", options: { color: C.muted, fontSize: 13, fontFace: FONT_BODY } },
      { text: "~2,200 ETH/day", options: { color: C.red, fontSize: 13, fontFace: FONT_BODY, bold: true, breakLine: true } },
      { text: "", options: { fontSize: 6, breakLine: true } },
      { text: "At 22 Gwei equilibrium gas, burn nearly offsets issuance. Current 0.1 Gwei is far below this threshold.", options: { color: C.dim, fontSize: 10, fontFace: FONT_BODY, italic: true } },
    ], {
      x: 5.5, y: 3.7, w: 4.0, h: 1.4, margin: 0, paraSpaceAfter: 6
    });
  }

  // ============================================================
  // SLIDE 6: Supply Projections (line chart)
  // ============================================================
  {
    const slide = pres.addSlide();
    slide.background = { color: C.bg_dark };
    addTopBar(slide, pres);
    addSlideNumber(slide, pres, 6);

    slide.addImage({ data: iconLine, x: 0.7, y: 0.25, w: 0.4, h: 0.4 });
    slide.addText("Long-Term Equilibrium: 125.7M ETH", {
      x: 1.2, y: 0.3, w: 8.1, h: 0.5,
      fontSize: 28, fontFace: FONT_HEAD, color: C.white, bold: true, margin: 0
    });
    slide.addText("200-Year Supply Projection — Issuance and Burn Converge at ~1,037K ETH/Year", {
      x: 0.7, y: 0.85, w: 8.6, h: 0.35,
      fontSize: 13, fontFace: FONT_BODY, color: C.muted, margin: 0
    });

    // Line chart: 200-year projection
    const years = [];
    const supply = [];
    for (let y = 0; y <= 200; y += 10) {
      years.push(`${2024 + y}`);
      const eq = 125.7;
      const start = 121.6;
      const val = eq - (eq - start) * Math.exp(-y / 40);
      supply.push(parseFloat(val.toFixed(2)));
    }

    slide.addChart(pres.charts.LINE, [{
      name: "ETH Supply (M)",
      labels: years,
      values: supply
    }], {
      x: 0.3, y: 1.3, w: 6.0, h: 3.3,
      lineSmooth: true,
      lineSize: 3,
      chartColors: [C.accent],
      showTitle: false,
      catAxisLabelColor: C.muted,
      catAxisLabelFontSize: 8,
      valAxisLabelColor: C.muted,
      valAxisLabelFontSize: 9,
      valGridLine: { color: C.bg_card, size: 0.5 },
      catGridLine: { style: "none" },
      showLegend: false,
      showMarker: true,
      markerSize: 4,
      chartArea: { fill: { color: C.bg_dark } },
      valAxisMinVal: 120,
      valAxisMaxVal: 127,
    });

    // Equilibrium annotation
    slide.addText("125.7M Equilibrium ▸", {
      x: 3.5, y: 1.65, w: 2.5, h: 0.25,
      fontSize: 9, fontFace: FONT_BODY, color: C.green, bold: true, margin: 0
    });

    // Right panel: Key parameters
    card(slide, pres, 6.6, 1.3, 3.1, 3.6);
    slide.addText("MODEL PARAMETERS", {
      x: 6.8, y: 1.45, w: 2.7, h: 0.3,
      fontSize: 10, fontFace: FONT_BODY, color: C.accent, bold: true, charSpacing: 2, margin: 0
    });

    const params = [
      { label: "ETH Staked", val: "39M ETH" },
      { label: "Avg Base Gas", val: "22 Gwei" },
      { label: "Equilibrium Supply", val: "125.7M ETH" },
      { label: "Annual Balance", val: "~1,037K ETH" },
      { label: "Staker Rewards", val: "2.7%/yr" },
      { label: "Non-staker Burn", val: "1.2%/yr" },
    ];
    params.forEach((p, i) => {
      const py = 1.9 + i * 0.5;
      slide.addText(p.label, {
        x: 6.8, y: py, w: 2.7, h: 0.2,
        fontSize: 9, fontFace: FONT_BODY, color: C.muted, margin: 0
      });
      slide.addText(p.val, {
        x: 6.8, y: py + 0.2, w: 2.7, h: 0.25,
        fontSize: 14, fontFace: FONT_HEAD, color: C.white, bold: true, margin: 0
      });
    });

    // Era transitions footer
    slide.addText("Eras: Genesis (5 ETH/blk) → Byzantium (3) → Constantinople (2) → Phase 0 → London Burn → Merge", {
      x: 0.7, y: 5.0, w: 8.0, h: 0.3,
      fontSize: 9, fontFace: FONT_BODY, color: C.dim, italic: true, margin: 0
    });
  }

  // ============================================================
  // SLIDE 7: Flippening & TVS (fixed progress bars)
  // ============================================================
  {
    const slide = pres.addSlide();
    slide.background = { color: C.bg_dark };
    addTopBar(slide, pres);
    addSlideNumber(slide, pres, 7);

    slide.addImage({ data: iconGlobe, x: 0.7, y: 0.25, w: 0.4, h: 0.4 });
    slide.addText("ETH at 18.7% of Bitcoin's Market Cap", {
      x: 1.2, y: 0.3, w: 8.1, h: 0.5,
      fontSize: 28, fontFace: FONT_HEAD, color: C.white, bold: true, margin: 0
    });
    slide.addText("Securing $307.6B in Total Value — Growing but Still Early Monetary Premium", {
      x: 0.7, y: 0.85, w: 8.6, h: 0.35,
      fontSize: 13, fontFace: FONT_BODY, color: C.muted, margin: 0
    });

    // Flippening progress - compact layout with visible bars
    slide.addText("FLIPPENING PROGRESS", {
      x: 0.7, y: 1.4, w: 4.0, h: 0.3,
      fontSize: 11, fontFace: FONT_BODY, color: C.accent, bold: true, charSpacing: 2, margin: 0
    });

    const flips = [
      { asset: "vs Bitcoin", pct: 18.70, color: C.orange },
      { asset: "vs USD", pct: 1.30, color: C.green },
      { asset: "vs Gold", pct: 0.89, color: "D4A843" },
    ];
    flips.forEach((f, i) => {
      const fy = 1.85 + i * 0.65;
      slide.addText(`${f.asset}`, {
        x: 0.7, y: fy, w: 1.3, h: 0.25,
        fontSize: 11, fontFace: FONT_BODY, color: C.light, margin: 0
      });
      slide.addText(`${f.pct}%`, {
        x: 2.0, y: fy, w: 0.8, h: 0.25,
        fontSize: 12, fontFace: FONT_HEAD, color: f.color, bold: true, margin: 0
      });
      // Progress bar background - full width, visible
      slide.addShape(pres.shapes.RECTANGLE, {
        x: 0.7, y: fy + 0.28, w: 4.0, h: 0.18,
        fill: { color: C.bg_card }
      });
      // Progress bar fill
      const fillW = Math.max(4.0 * (f.pct / 100), 0.08);
      slide.addShape(pres.shapes.RECTANGLE, {
        x: 0.7, y: fy + 0.28, w: fillW, h: 0.18,
        fill: { color: f.color }
      });
    });

    // TVS pie chart - right side
    slide.addChart(pres.charts.PIE, [{
      name: "TVS",
      labels: ["ETH ($272.76B)", "ERC20s ($22.21B)", "NFTs ($12.66B)"],
      values: [272.76, 22.21, 12.66]
    }], {
      x: 5.0, y: 1.2, w: 4.7, h: 2.8,
      showTitle: true, title: "Total Value Secured: $307.6B",
      titleColor: C.light, titleFontFace: FONT_BODY, titleFontSize: 12,
      chartColors: [C.accent, C.accent2, C.green],
      showPercent: true,
      dataLabelColor: C.light,
      dataLabelFontSize: 10,
      showLegend: true, legendPos: "b", legendColor: C.muted, legendFontSize: 9,
    });

    // Bottom detail cards
    const detY = 4.1;
    card(slide, pres, 0.7, detY, 4.3, 1.1);
    slide.addText("TOP ERC20s BY VALUE", {
      x: 0.9, y: detY + 0.1, w: 3.9, h: 0.25,
      fontSize: 9, fontFace: FONT_BODY, color: C.accent2, bold: true, charSpacing: 2, margin: 0
    });
    slide.addText("Dai $4.41B  •  Shiba Inu $3.51B\nCronos $2.97B  •  Tether Gold $2.65B", {
      x: 0.9, y: detY + 0.4, w: 3.9, h: 0.6,
      fontSize: 11, fontFace: FONT_BODY, color: C.light, margin: 0
    });

    card(slide, pres, 5.3, detY, 4.4, 1.1);
    slide.addText("TOP NFT COLLECTIONS", {
      x: 5.5, y: detY + 0.1, w: 4.0, h: 0.25,
      fontSize: 9, fontFace: FONT_BODY, color: C.green, bold: true, charSpacing: 2, margin: 0
    });
    slide.addText("CryptoPunks $2.13B  •  BAYC $0.68B\nENS $0.63B  •  Pudgy Penguins $0.51B", {
      x: 5.5, y: detY + 0.4, w: 4.0, h: 0.6,
      fontSize: 11, fontFace: FONT_BODY, color: C.light, margin: 0
    });
  }

  // ============================================================
  // SLIDE 8: Key Takeaways (improved layout)
  // ============================================================
  {
    const slide = pres.addSlide();
    slide.background = { color: C.bg_dark };

    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.accent }
    });
    addSlideNumber(slide, pres, 8);

    slide.addImage({ data: iconTarget, x: 0.7, y: 0.3, w: 0.4, h: 0.4 });
    slide.addText("Key Takeaways", {
      x: 1.2, y: 0.3, w: 8.0, h: 0.5,
      fontSize: 30, fontFace: FONT_HEAD, color: C.white, bold: true, margin: 0
    });
    slide.addText("Ultra Sound Money Thesis Intact — Gas Activity Is the Critical Variable", {
      x: 0.7, y: 0.85, w: 8.6, h: 0.35,
      fontSize: 13, fontFace: FONT_BODY, color: C.accent, margin: 0
    });

    // 3-2 grid layout: row 1 has 3, row 2 has 2 (centered)
    const takeaways = [
      { num: "01", title: "Mildly Inflationary Today", body: "+0.83%/yr due to historically low gas (0.1 Gwei). Burns offset only ~1% of issuance.", color: C.red },
      { num: "02", title: "Burn Mechanism Works", body: "EIP-1559 requires sustained on-chain activity. DeFi and transfers drive 85% of burn.", color: C.orange },
      { num: "03", title: "Significant Supply Lock", body: "38.9M ETH (32%) staked. 9.1M ETH locked avg 10.7 years. Validators earn ~2.9% APR.", color: C.green },
      { num: "04", title: "Structural Equilibrium", body: "125.7M ETH long-term target at 22 Gwei avg gas. Issuance-burn balance at ~1,037K ETH/yr.", color: C.accent },
      { num: "05", title: "Growing Monetary Premium", body: "$307B+ TVS, 18.7% of Bitcoin's market cap. Early but demonstrating real value capture.", color: C.accent2 },
    ];

    // Row 1: 3 cards
    const cw1 = 2.85;
    const gap = 0.15;
    for (let i = 0; i < 3; i++) {
      const t = takeaways[i];
      const tx = 0.7 + i * (cw1 + gap);
      const ty = 1.4;
      card(slide, pres, tx, ty, cw1, 1.4);
      // Number badge
      slide.addShape(pres.shapes.RECTANGLE, {
        x: tx + 0.15, y: ty + 0.15, w: 0.4, h: 0.4,
        fill: { color: t.color, transparency: 20 }
      });
      slide.addText(t.num, {
        x: tx + 0.15, y: ty + 0.15, w: 0.4, h: 0.4,
        fontSize: 15, fontFace: FONT_HEAD, color: t.color, bold: true, align: "center", valign: "middle", margin: 0
      });
      slide.addText(t.title, {
        x: tx + 0.65, y: ty + 0.12, w: cw1 - 0.85, h: 0.3,
        fontSize: 13, fontFace: FONT_HEAD, color: C.white, bold: true, margin: 0
      });
      slide.addText(t.body, {
        x: tx + 0.65, y: ty + 0.48, w: cw1 - 0.85, h: 0.8,
        fontSize: 10, fontFace: FONT_BODY, color: C.light, margin: 0
      });
    }

    // Row 2: 2 cards centered
    const cw2 = 4.35;
    for (let i = 0; i < 2; i++) {
      const t = takeaways[3 + i];
      const tx = 0.7 + i * (cw2 + gap);
      const ty = 3.0;
      card(slide, pres, tx, ty, cw2, 1.2);
      slide.addShape(pres.shapes.RECTANGLE, {
        x: tx + 0.15, y: ty + 0.15, w: 0.4, h: 0.4,
        fill: { color: t.color, transparency: 20 }
      });
      slide.addText(t.num, {
        x: tx + 0.15, y: ty + 0.15, w: 0.4, h: 0.4,
        fontSize: 15, fontFace: FONT_HEAD, color: t.color, bold: true, align: "center", valign: "middle", margin: 0
      });
      slide.addText(t.title, {
        x: tx + 0.65, y: ty + 0.12, w: cw2 - 0.85, h: 0.3,
        fontSize: 13, fontFace: FONT_HEAD, color: C.white, bold: true, margin: 0
      });
      slide.addText(t.body, {
        x: tx + 0.65, y: ty + 0.48, w: cw2 - 0.85, h: 0.6,
        fontSize: 10, fontFace: FONT_BODY, color: C.light, margin: 0
      });
    }

    // Closing bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 4.5, w: 10, h: 0.55,
      fill: { color: C.bg_card }
    });
    slide.addText("The ultra sound money thesis depends on gas activity recovery — monitor base gas trends as the leading indicator.", {
      x: 0.7, y: 4.55, w: 8.0, h: 0.45,
      fontSize: 11, fontFace: FONT_BODY, color: C.accent, italic: true, valign: "middle", margin: 0
    });
  }

  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Deck saved to /app/output/final_deck.pptx");
}

buildDeck().catch(err => { console.error(err); process.exit(1); });

